     1	/**
     2	 * Recipe guards — regression tests for four failure modes that reached a feature branch
     3	 * despite passing `tsc`, `eslint`, `vitest`, CodeRabbit and the Storybook a11y run.
     4	 *
     5	 * All four share a shape: the value is a *valid* `SystemStyleObject` entry, so TypeScript is
     6	 * satisfied; no lint rule covers it; and nothing asserts layout. Each one renders plausible,
     7	 * wrong output that is only visible by opening the page.
     8	 *
     9	 *   1. A spacing-scale key on a sizing property. Chakra resolves `width`/`height`/`boxSize`
    10	 *      through `theme.sizes`, not `theme.space`. The Zimmermann named scale is registered as
    11	 *      `space` only (deliberately — see foundation/sizes.ts), so `width: 'xl'` silently reads
    12	 *      Chakra's default `sizes.xl` = 36rem. It shipped a 576px icon and collapsed the footer.
    13	 *
    14	 *   2. The same trap on a typography property. `fontSizes`/`lineHeights`/`letterSpacings` are
    15	 *      deliberately NOT registered either (theme/index.ts explains why), so a bare key reads
    16	 *      Chakra's default or resolves to nothing at all. See TYPOGRAPHY_PROPS below.
    17	 *
    18	 *   3. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
    19	 *      `extendTheme(baseTheme, overrides)`, which DEEP MERGES — a recipe named `Footer` does
    20	 *      not replace SFCC's `Footer`, it inherits it. Shared part names then pick up base
    21	 *      properties, and a key you add that the base lacks is appended last, so a CSS shorthand
    22	 *      can silently reset a longhand the base declared earlier.
    23	 *
    24	 *   4. A bare scale key inside a compound shorthand. Chakra resolves a token only when it is
    25	 *      the entire value; `padding: 'xs 0'` is emitted verbatim, the browser rejects the
    26	 *      declaration, and the padding does not apply at all.
    27	 *
    28	 * SCOPE: these guards walk the registered recipe map only (`components` + the composed
    29	 * `theme`). They cannot see the same mistakes made as a JSX prop on a component — there is a
    30	 * live instance of failure mode 2 at `overrides/app/components/header/index.tsx:302`
    31	 * (`fontSize="l"`, which emits nothing) that no test here can reach. Catching that class needs
    32	 * a static rule over JSX attributes (`.coderabbit/ast-grep-rules/`), not a theme walk.
    33	 */
    34	import { describe, expect, test } from 'vitest';
    35	import theme from '../index';
    36	import { components } from './index';
    37	import { breakpoints } from '../foundation/gridSystem';
    38	import { fontSizes, letterSpacings, lineHeights } from '../foundation/typography';
    39	import { spacing } from '../foundation/spacing';
    40	
    41	const SPACING_KEYS = Object.keys(spacing);
    42	
    43	const SIZING_PROPS = new Set([
    44	  'width',
    45	  'height',
    46	  'minWidth',
    47	  'maxWidth',
    48	  'minHeight',
    49	  'maxHeight',
    50	  'boxSize',
    51	  'w',
    52	  'h',
    53	  'minW',
    54	  'maxW',
    55	  'minH',
    56	  'maxH',
    57	]);
    58	
    59	/**
    60	 * Typography properties whose Zimmermann scale is deliberately not registered as a Chakra
    61	 * scale, mapped to the keys that must never appear bare on them. Each set is that property's
    62	 * own Zimmermann scale keys ∪ the spacing keys, because both spellings fail — differently:
    63	 *
    64	 *   fontSize: '2xs' → resolves against Chakra's default fontSizes: 0.625rem (10px), where the
    65	 *                     Zimmermann `2xs` (0.875rem / 14px) was intended. Plausible, wrong size.
    66	 *   fontSize: '4xs' → no Chakra key, so `font-size: 4xs` is emitted and the browser drops the
    67	 *                     declaration outright. Same for every `lineHeight`/`letterSpacing` key,
    68	 *                     none of which collide with a Chakra default.
    69	 *   fontSize: 'l'   → a spacing key that is not a fontSizes key: dropped the same way.
    70	 *
    71	 * `fontSizes` is the only one of the three with genuine wrong-value collisions; the other two
    72	 * only ever drop the declaration. Both outcomes are worth guarding.
    73	 *
    74	 * Set type with `textStyle` (all 22 Handover styles ARE registered) or var(--zimm-font-*).
    75	 * `fontWeight` is deliberately absent: `medium` is a key in both scales and resolves to 500
    76	 * either way, so keying it the same way would flag a correct declaration.
    77	 */
    78	const TYPOGRAPHY_PROPS = new Map<string, Set<string>>([
    79	  ['fontSize', new Set([...Object.keys(fontSizes), ...SPACING_KEYS])],
    80	  ['lineHeight', new Set([...Object.keys(lineHeights), ...SPACING_KEYS])],
    81	  ['letterSpacing', new Set([...Object.keys(letterSpacings), ...SPACING_KEYS])],
    82	]);
    83	
    84	/** Properties that resolve through `theme.space`, where a bare scale key is correct. */
    85	const SPACE_SHORTHANDS = new Set(['padding', 'margin', 'inset', 'gap', 'p', 'm']);
    86	
    87	/** Derived from the registered breakpoints so the two cannot drift apart. */
    88	const BREAKPOINT_KEYS = new Set(Object.keys(breakpoints));
    89	
    90	/**
    91	 * True when `n` is a responsive *value* container — an array (`['xl','2xl']`) or a
    92	 * breakpoint-keyed object (`{base:'xl', md:'2xl'}`) — rather than a style object. Its keys are
    93	 * therefore positions, not property names, and the property name has to come from the parent.
    94	 *
    95	 * The test is deliberately "are ALL the keys breakpoints?" and not "is ANY key a breakpoint?".
    96	 * That is load-bearing: `xl` and `2xl` are keys in `breakpoints` AND in `spacing`, and
    97	 * `sm`/`md`/`lg` are keys in `breakpoints` AND in `fontSizes`/`lineHeights`/`letterSpacings`.
    98	 * A per-key test cannot tell a responsive map apart from a style object, so only the all-keys
    99	 * form works.
   100	 *
   101	 * A Chakra `sizes`/`variants` map whose every member happens to be named after a breakpoint
   102	 * (`sizes: {md: {...}, lg: {...}}`) does read as responsive here, but harmlessly: the level
   103	 * below it is a real style object, which re-establishes the property name before any leaf is
   104	 * reported.
   105	 */
   106	const isResponsiveContainer = (n: object): boolean =>
   107	  Array.isArray(n) || (Object.keys(n).length > 0 && Object.keys(n).every((k) => BREAKPOINT_KEYS.has(k)));
   108	
   109	type Found = { recipe: string; path: string; prop: string; value: string };
   110	
   111	/**
   112	 * Recursively walk a style object, including nested media queries, pseudo-selectors and
   113	 * responsive containers. `prop` carries the nearest enclosing property name forward so a leaf
   114	 * inside a responsive container is attributed to the property, not to `0` or `base`.
   115	 */
   116	const walk = (node: unknown, recipe: string, path: string, prop: string, hit: (f: Found) => void): void => {
   117	  if (node === null || typeof node !== 'object') return;
   118	  const responsive = isResponsiveContainer(node);
   119	  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
   120	    const here = path ? `${path}.${key}` : key;
   121	    const p = responsive ? prop : key;
   122	    if (value !== null && typeof value === 'object') {
   123	      walk(value, recipe, here, p, hit);
   124	    } else if (typeof value === 'string') {
   125	      hit({ recipe, path, prop: p, value });
   126	    }
   127	  }
   128	};
   129	
   130	/**
   131	 * `recipe.path.prop: 'value'`. For a responsive hit `path` already ends in the property name
   132	 * (the array/breakpoint object sits *under* `fontSize`), so appending `prop` again would read
   133	 * `…fontSize.fontSize`.
   134	 */
   135	const where = (f: Found): string => {
   136	  const segments = f.path ? f.path.split('.') : ['baseStyle'];
   137	  if (segments[segments.length - 1] !== f.prop) segments.push(f.prop);
   138	  return `${f.recipe}.${segments.join('.')}: '${f.value}'`;
   139	};
   140	
   141	/** baseStyle may be a plain object or a function of props (see zimmTextInput). */
   142	const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
   143	  const bs = recipe.baseStyle;
   144	  if (typeof bs !== 'function') return bs;
   145	  return (bs as (p: Record<string, unknown>) => unknown)({
   146	    inverse: false,
   147	    disabled: false,
   148	    hasError: false,
   149	    focused: false,
   150	    filled: false,
   151	    theme,
   152	    colorMode: 'light',
   153	  });
   154	};
   155	
   156	const collect = (): Found[] => {
   157	  const found: Found[] = [];
   158	  for (const [name, recipe] of Object.entries(components)) {
   159	    const r = recipe as unknown as Record<string, unknown>;
   160	    for (const section of [resolveBaseStyle(r), r.variants, r.sizes]) {
   161	      walk(section, name, '', '', (f) => found.push(f));
   162	    }
   163	  }
   164	  return found;
   165	};
   166	
   167	describe('recipe guards', () => {
   168	  test('collect() actually walks the registered recipes', () => {
   169	    // Every other test here asserts an empty offender list, which an empty input satisfies
   170	    // just as well as a clean one. Without this, deleting `components` would turn the whole
   171	    // file green.
   172	    expect(Object.keys(components).length).toBeGreaterThan(0);
   173	    expect(collect().length).toBeGreaterThan(0);
   174	  });
   175	
   176	  test('no sizing property uses a bare spacing-scale key', () => {
   177	    const offenders = collect()
   178	      .filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value))
   179	      .map(where);
   180	
   181	    // `width: 'xl'` reads theme.sizes.xl (36rem), not space.xl (1.5rem).
   182	    // Use var(--zimm-scale-*), an imported constant, or an explicit unit instead.
   183	    expect(offenders).toEqual([]);
   184	  });
   185	
   186	  test('no typography property uses a bare scale key', () => {
   187	    const offenders = collect()
   188	      .filter((f) => TYPOGRAPHY_PROPS.get(f.prop)?.has(f.value) ?? false)
   189	      .map(where);
   190	
   191	    // `fontSize: '2xs'` reads Chakra's fontSizes (10px), not the Zimmermann scale (14px);
   192	    // `lineHeight: '2xs'` resolves to nothing at all. Use textStyle or var(--zimm-font-*).
   193	    expect(offenders).toEqual([]);
   194	  });
   195	
   196	  test('no compound shorthand contains a bare scale key', () => {
   197	    const offenders = collect()
   198	      .filter((f) => {
   199	        if (!SPACE_SHORTHANDS.has(f.prop)) return false;
   200	        if (!f.value.includes(' ')) return false; // single token is fine
   201	        // Split on whitespace outside var(...) and look for a bare scale key.
   202	        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
   203	        return parts.some((part) => SPACING_KEYS.includes(part));
   204	      })
   205	      .map(where);
   206	
   207	    // Chakra resolves a token only as a whole value. `padding: 'xs 0'` is emitted verbatim
   208	    // and the browser drops the declaration. Use paddingY/paddingX or a var() instead.
   209	    expect(offenders).toEqual([]);
   210	  });
   211	
   212	  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
   213	    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
   214	    // base variants, and Header/ListMenu are partial overrides of components whose other
   215	    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
   216	    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];
   217	
   218	    const unexpected = Object.keys(components)
   219	      .filter((name) => !INTENTIONAL_MERGES.includes(name))
   220	      .filter((name) => {
   221	        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
   222	        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
   223	        const ourKeys = new Set(Object.keys(ours as object));
   224	        // A key present after composition that we never declared came from the base theme.
   225	        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
   226	      });
   227	
   228	    expect(unexpected).toEqual([]);
   229	  });
   230	});

