    29	  },
    30	  play: async ({ canvasElement }) => {
    31	    const canvas = within(canvasElement);
    32	
    33	    const homeLink = canvas.getByRole('link', { name: 'Home' });
    34	    const newLink = canvas.getByRole('link', { name: 'New' });
    35	    const dressesLink = canvas.getByRole('link', { name: 'Dresses' });
    36	
    37	    await expect(homeLink).toBeVisible();
    38	    await expect(newLink).toBeVisible();
    39	    await expect(dressesLink).toBeVisible();
